float wave1( float x, float dxdt, in vec2 v, float t , float w)
{   float f2;
    float sampleX=0.0;
    float f=w;
    float v1,v2;

    v1=squareWave250(f,t);
    v2=triangleWave250(f,t);

    sampleX =((v1+v2)/2.0)*exp(-0.5*t);
