    //float f2b=(sampleX+(sawf(t,f)+sawf(t,f+f/2.0)+sawf(t,f-f/2.0)/3.0))/2.0;

    float fx=f2a*1.5*exp(-1.25*t);
    return fx;
}


float D3(float ton, float tid, float toff)
{   vec3 n3;
    float resp;
    n3=vec3(ton,tid, toff);


    if(ms>=ton && ms<=toff)
    {      // lower one octave
      n3.y -=12.; //12 notas
      //n3.y +=12.; //12 notas

      // compute note frequency and time  
      float f = 440.0*pow( 2.0, float(n3.y-69.)/12.0 );
      float t = mtime - float(n3.x)/mtempo;
      if( n3.x==0.0 ) return 0.0;

      // prepare wave parameters
      float w = tau*f;

      float dwdt = w/iSampleRate; // derivative

      // mix between bandlimited and raw saw waves  
      vec2 v = smoothstep(-0.2,0.2,sin(t*vec2(1.0,0.5)) );
      // build instrument

      float f1,y;
      f1=wave1(w*t,1.00*dwdt,v,t,w);

      float wf  = 0.4*f1;
      y=f1*wf;
      float offset=n3.x;
       y*=exp(-1.0/n3.z * (t -offset) );

       mresp+=y;
    }

}



